# -*- coding: utf-8 -*-
"""B-lens 設計の巡・第一巡の「再現の表（K295〜）」と「採否表（P495〜）と裁定の候補（D168〜）」を組む。
結果の欄の数は verify-Blens-design-r1.json と、票の器の走らせ直しの記録（claude-ai-2/gate_null_sim-run-2026-09-23.txt）から機械で入れる。
用法: python records/reviews/Blens/design-round1/make_records_Blens_design_r1.py"""
import os, re, json, math, hashlib

HERE = os.path.dirname(os.path.abspath(__file__))
NL = chr(10)
V = json.load(open(os.path.join(HERE, 'verify-Blens-design-r1.json'), encoding='utf-8'))
RUN = open(os.path.join(HERE, 'claude-ai-2', 'gate_null_sim-run-2026-09-23.txt'), encoding='utf-8').read()
assert RUN.strip().endswith('rc=0'), '器の走らせ直しが終わっていない'
null_rows = re.findall(r'tau=([0-9.]+).*?自由な並べ替え ([0-9.]+)／方向を単位 ([0-9.]+)', RUN)
alt_rows = re.findall(r'物差しが担う分 ([0-9.]+)）: 通過率 自由 ([0-9.]+)／方向を単位 ([0-9.]+)', RUN)
assert len(null_rows) == 4 and len(alt_rows) == 3, (null_rows, alt_rows)
sim_sha = hashlib.sha256(open(os.path.join(HERE, 'claude-ai-2', 'gate_null_sim.py'), 'rb').read()).hexdigest().upper()[:16]
s16 = lambda p: hashlib.sha256(open(p, 'rb').read().replace(b'\r\n', b'\n')).hexdigest().upper()[:16]
f7, f6 = math.factorial(7), math.factorial(6)
dec_pairs = lambda L: '・'.join('%s' % p for p in L)
frag_chars = [c for c, v in V['V3']['chars'].items() if v['fragment']]
x4 = V['V4']
x_stem = '／'.join('%s の %s: %s' % (sc, {'a': 'X_a', 'others': 'X_o'}[k], '・'.join('「%s」（%s）' % (t[1], '・'.join(x for x in (t[2], t[3]) if x)) for t in x4[sc][k]))
                   for sc in ('N1', 'S1') for k in ('a', 'others') if x4[sc][k])
ov = V['V5']
ov_txt = '・'.join('%s：%s' % (k, '・'.join('「%s」' % t[1] for t in v)) for k, v in ov.items() if k in ('E_td&F_prose', 'X_surv_o&F_prose', 'F_prose&E_static-_all', 'E_static-&E_td'))
s4 = V['V14']
s4_txt = '／'.join('%s: %s' % (arm, '・'.join('%s %s' % tuple(x) for x in rows)) for arm, rows in s4.items() if arm in ('Osec-Ncold+vrand', 'O-Ncold+vrand', 'O-Ncold-vrand', 'Onull+vrand'))
sims = '／'.join('効きの幅 %s: 自由 %s・方向を単位 %s' % r for r in null_rows)
alts = '／'.join('物差しが担う分 %s: 自由 %s・方向を単位 %s' % r for r in alt_rows)

V2, V2c, V2w, V15 = V['V2'], V['V2c'], V['V2w'], V['V15']
FRC = chr(0xFFFD)
assert V2w['n_same_intended'] == 8 and V2w['incidental'] and all(v == ['-現れ'] for v in V2w['incidental'].values()), V2w['incidental']
assert '現れ' in V2w['Nk_text'] and '現れ' in V2w['ncold_text']
units = [V2w['n_same_intended'], V2w['n_same_word'], V2c['n_same_content_E'], V2['n_same_E']]
u_lo, u_hi = min(units), max(units)
assert u_hi == 8 and u_lo == 1, units
on_ctx = '・'.join('「%s」' % c.replace(FRC, '') for c in V2c['Onull_contexts'])
incid_arms = '・'.join(sorted(V2w['incidental']))
assert V15['readme_commit'] == 'bb8e27b' and V15['has_sekkeichu_anywhere'] is False and V15['now_line_count'] == 1
assert V15['now_line_status'] == '凍結した' and V15['now_says_no_main_data'] and V15['now_says_next_main_run'] and V15['has_results_line'] and not V15['heading_mentions_results']
json_cells = '・'.join('%s の %s に %d 件' % (tuple(c.split('|')) + (n,)) for c, n in V['V6']['json_direct_by_cell'].items())

K = ['| 番号 | 誰の主張 | 主張 | 確かめ方 | 結果 |', '|---|---|---|---|---|']
def k(no, who, claim, how, res):
    K.append('| K%d | %s | %s | %s | %s |' % (no, who, claim, how, res))

